style:
.etp-steps {
  display: flex;
  align-items: stretch;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
  padding: 14px 16px;
  border-radius: 12px;
  background: #ffffff;
  border: 1px solid #e4e7ec;
  box-shadow: 0 1px 2px rgba(16, 24, 40, 0.04);
}
.etp-steps__item {
  flex: 1 1 150px;
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 52px;
  padding: 8px 10px;
}
.etp-steps__n {
  flex: 0 0 26px;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
  color: #ffffff;
  background: #1f4b99;
}
.etp-steps__t {
  font-size: 13px;
  font-weight: 650;
  color: #101828;
  line-height: 1.2;
}
.etp-steps__s {
  font-size: 11px;
  color: #667085;
  margin-top: 2px;
}
.etp-steps__divider {
  flex: 0 0 1px;
  width: 1px;
  background: #e4e7ec;
  align-self: stretch;
  margin: 6px 0;
}
@media (max-width: 900px) {
  .etp-steps__divider { display: none; }
}
